def binary_search(sorted_items, wanted):
    low, high = 0, len(sorted_items) - 1
    while low <= high:
        mid = (low + high) // 2
        if sorted_items[mid] < wanted:
            low = mid + 1
        elif sorted_items[mid] > wanted:
            high = mid - 1
        else:
            return mid
    return -1

